    // Collect any parentheses between the `**` and the dict's opening brace.
    // The dict may be wrapped in one or more parentheses, e.g. `**({"a": 1})`.
    let mut parens = Vec::new();
    for tok in SimpleTokenizer::starts_at(doublestar.end(), source).skip_trivia() {
