        match tok.kind() {
            SimpleTokenKind::LParen => parens.push(tok.range()),
            _ => return None,
        }
    }

    let mut edits = vec![];

    // Delete the opening `{` and any wrapping parentheses. Comments between
    // the tokens are preserved by deleting each token individually.
    push_deletion(&mut edits, dict_start..dict_start + TextSize::from(1));
    for range in &parens {
        push_deletion(&mut edits, *range);
    }

    // Delete the parentheses that close the ones preceding the dict.
    let mut delete_trailing_parens = |edits: &mut Vec<Edit>, start: TextSize| -> bool {
        let mut remaining = parens.len();
        for tok in SimpleTokenizer::starts_at(start, source).skip_trivia() {
            match tok.kind() {
                SimpleTokenKind::RParen if remaining > 0 => {
                    push_deletion(edits, tok.range());
                    remaining -= 1;
                }
                _ => break,
            }
        }
        remaining == 0
