            Some(key) => key.range().end().max(value_range.end()),
            None => value_range.end(),
        };

        for tok in SimpleTokenizer::starts_at(scan_from, source).skip_trivia() {
            match tok.kind() {
                SimpleTokenKind::Comma => {
                    push_deletion(&mut edits, tok.range());
                }
                SimpleTokenKind::RBrace => {
                    push_deletion(&mut edits, tok.range());
                    if !delete_trailing_parens(&mut edits, tok.end()) {
                        return None;
                    }
                    break;
                }
                _ => {}
            }
        }
        Some(Fix::safe_edits(
            // Delete the `**`
            Edit::range_deletion(doublestar.range()),
            edits,
        ))
    } else {
        // Ex) `**{}`
        push_deletion(&mut edits, dict_start..dict_end);
        if !delete_trailing_parens(&mut edits, dict_end) {
            return None;
        }
        Some(Fix::safe_edits(
            // Delete the `**`
            Edit::range_deletion(doublestar.range()),
            edits,
        ))
    }
